export function isBuiltin(name, ecosystem) {
  if (!name) return false;
  const cleaned = String(name).trim().toLowerCase();
  if (ecosystem === 'npm') {
    if (cleaned.startsWith('node:')) return true;
    const base = cleaned.split('/')[0];
    return NODE_BUILTINS.has(base);
  }
  if (ecosystem === 'pypi') {
    const base = cleaned.split('.')[0];
    return PYTHON_BUILTINS.has(base);
  }
  return false;
}
